SR = R.SR
WIN = 8.0
POS_DB = {"near": 0.0, "across": -4.0, "door": -8.0}
DUR = {"knock": (0.6, 1.8), "doorbell": (1.0, 2.5), "phone": (1.0, 3.0), "vibration": (1.0, 3.0),
       "intercom": (1.0, 2.5)}
