ASSISTANT_PIPER = 0                                 # Piper libritts speaker for the assistant (not a user voice)


def seed_of(*parts):
    return int(hashlib.sha256("|".join(map(str, parts)).encode()).hexdigest()[:12], 16)


class Assets:
    def __init__(self, split):
        self.split = split
        aux = json.load(open("results/step0/aux_splits.json", encoding="utf-8"))
        a = "test" if split == "replication" else split
        self.voices, self.rooms, self.envs = aux["voices"][a], aux["rooms"][a], aux["noise_envs"][a]
        self.piper = aux["piper_speakers"].get(split, [])
        assert ASSISTANT_PIPER not in aux["piper_speakers"]["test"] + aux["piper_speakers"]["replication"]
        la = json.load(open("results/step0/line_assignment.json", encoding="utf-8"))
        self.convs = la["conversations"][split]
        self.v3lines = {k: la["lines"][k].get(split, []) for k in ("he_door", "he_phone", "f3_pair", "b2_side")}
        self.flip = {k: la["flip"][f"{k}_flip"] for k in ("phone", "door")}
        lv_path = "results/step0_v04/lines_v04.json"
        lv = json.load(open(lv_path, encoding="utf-8")) if os.path.exists(lv_path) else \
            {"pools": {}, "backchannel_common": [], "conv": {}}
        self.pool = {k: lv["pools"][k][split] for k in lv["pools"]}
        self.backchannel = lv["backchannel_common"]
        cl = json.load(open("data/lines_v04/convlines_candidates.json", encoding="utf-8"))
        self.reject = {"phone": {}, "door": {}}
        for which, d in lv["conv"].items():
            w = which.split("_")[1]
            for cid, flags in d.items():
                if flags["split"] != split:
                    continue
                idx = int(cid.rsplit("_", 1)[1])
                ok = [cl[w][cid][f] for f in ("plain", "hello_start") if flags.get(f) and cl[w][cid].get(f)]
                if ok:
                    self.reject[w][idx] = {f: cl[w][cid][f] for f in ("plain", "hello_start")
                                           if flags.get(f) and cl[w][cid].get(f)}
        self.clips, self.group, self.kind, self.decoy_class = {}, {}, {}, {}
        man = json.load(open("results/step0/split_final.json", encoding="utf-8"))["manifest"]
        pools = json.load(open("results/step0/event_decoy_pools.json", encoding="utf-8"))["clips"]
        for k, v in man.items():
            if v.get("split") != split:
                continue
            pool = {"unseen_vibration": "vibration", "unseen_intercom": "intercom"}.get(v.get("pool", ""), v.get("pool"))
            path = f"data/fsd50k_sel/{k}.wav"
            self._add(pool, path, v["group"])
            if pool == "decoy":
                self.decoy_class[path] = pools[k]["fsd50k_class"]
        if split == "test":
            for pool, names in COMMONS.items():
                for n in names:
                    self._add(pool, f"data/commons4_testonly/{n}", f"commons:{n}")
        ns = json.load(open("results/step0_v04/new_split.json", encoding="utf-8"))["manifest"]
        for k, m in ns.items():
            if m["split"] == split:
                self._add(m["class"], f"data/fsd50k_sel/{k}.wav", m["group"], kind=m["kind"])
        self.new = {p: [] for p in ("phone", "doorbell", "knock", "vibration", "intercom", "door")}
        if split in ("test", "replication"):
            fs = json.load(open("results/step0/freesound_new_subset.json", encoding="utf-8"))["kept"]
            for sid, v in fs.items():
                p = glob.glob(f"data/freesound_new/raw/{sid}.*")
                if v["split"] == split and sid not in FS_NEW_DROP and p:
                    path = p[0].replace("\\", "/")
                    self.new[v["pool"]].append(path)
                    self.group[path] = f"fsn:{v['uploader']}"
            fd = json.load(open("results/step0_v04/freesound_doors.json", encoding="utf-8"))["assign"]["manifest"]
            for sid, m in fd.items():
                p = glob.glob(f"data/freesound_doors/raw/{sid}.*")
                if m["split"] == split and p:
                    path = p[0].replace("\\", "/")
                    self.new["door"].append(path)
                    self.group[path], self.kind[path] = m["group"], m["kind"]
        self.new_door = set(self.new["door"])
        tv = json.load(open("results/step0_v04/tv_speech.json", encoding="utf-8"))["manifest"]
        self.tv = [m["path"] for m in tv.values() if m["split"] == split]
        for m in tv.values():
            if m["split"] == split:
                self.group[m["path"]] = f"tv:{m['speaker']}"
        # plan 8.4: TV speakers who are in the speaker-ID model's training data (VoxCeleb), or who cannot be checked
        # (no name), are not used for new units (scripts/step0v4_speaker_overlap.py); the full pool stays in self.tv
        # for the checks of units rendered before 2026-11-15.
        ex_path = "results/step0_v04/tv_speaker_exclude.json"
        ex = set(json.load(open(ex_path, encoding="utf-8"))["exclude"]) if os.path.exists(ex_path) else set()
        self.tv_plan = [m["path"] for m in tv.values() if m["split"] == split and str(m["speaker"]) not in ex]
        self.pos = json.load(open("results/step0_v04/rir_positions.json", encoding="utf-8"))

    def _add(self, pool, path, group, kind=None):
        self.clips.setdefault(pool, []).append(path)
        self.group[path] = group
        if kind:
            self.kind[path] = kind

    def rir(self, rng, room, pos):
        return rng.choice(self.pos[room][pos])

    def walk(self, rng, room, n, away=True):
        """n RIRs of increasing (away) or decreasing distance: footsteps walking away from or back to the mic."""
        rows = self.pos[room]["by_distance"]
        m = len(rows)
        cuts = np.linspace(0.15, 0.95, n) if away else np.linspace(0.95, 0.15, n)
        return [rows[min(m - 1, int(c * m) + int(rng.integers(-2, 3)))][0] for c in cuts]


EPISODE_SCRIPT_FILES = ("data/episodes_v04/episodes_candidates.json", "data/episodes_v04/episodes2_candidates.json",
                        "data/episodes_v04/episodes_regen_candidates.json")


def load_episode_scripts():
    """{episode id: turns}: the generated scripts, the second-prompt scripts and the rewritten ones, in that order (a
    rewrite keeps its id and replaces the first version). The pilot file is not part of the set (it reuses some ids)."""
    eps = {}
    for f in EPISODE_SCRIPT_FILES:
        if os.path.exists(f):
            eps.update(json.load(open(f, encoding="utf-8")))
    return eps


DOOR_TYPES = ("door", "door_open", "door_close")


def cap_type(s, A, door_by_source=True):
    """Recording type of a unit's source for the plan 5.6 caps: its role or class. Door sounds are typed by source
    (the post-2023 Freesound doors of test and replication apart), as the planner caps them (s_move:door_<source>,
    episode:door_open_<source>, episode:door_close_<source>) and as S-move is reported (plan 5.2: by door source).
    door_by_source=False is the earlier measure (sources pooled), with which dev and test were trimmed."""
    t = s.get("role") or s.get("cls") or ("tv" if s.get("kind") == "tvfile" else "other")
    if door_by_source and t in DOOR_TYPES and s.get("path") in A.new_door:
        t += "_freesound"
    return t


class Capper:
    """Per-split cap on how often one recording group is used within a part (plan 5.6). Uses are logged per planned
    unit, so a unit that fails to build gives its uses back (release). totals: {cap key: number of units of the split
    that use it} (the share's denominator, as the leak check measures it); when a key has a total there, it replaces
    the total passed by the planner."""
    def __init__(self, share, totals=None):
        self.share, self.count, self.log = share, {}, []
        self.totals = dict(totals or {})

    def ok(self, part, group, total, n_groups):
        cap = max(self.share, 1.0 / max(1, n_groups))
        total = self.totals.get(part, total)
        return self.count.get((part, group), 0) < max(1, int(np.ceil(cap * total)))

    def use(self, part, group):
        self.count[(part, group)] = self.count.get((part, group), 0) + 1
        self.log.append((part, group))

    def release(self, uses):
        for key in uses:
            self.count[tuple(key)] = max(0, self.count.get(tuple(key), 0) - 1)


def pick_clip(rng, A, cls, part, total, capper, paths=None, kinds=None, n_groups=None):
    """n_groups: the number of groups the cap is shared by, when paths is a subset of the pool (default: the groups
    among paths)."""
    paths = list(paths if paths is not None else A.clips.get(cls, []))
    if kinds:
        paths = [p for p in paths if A.kind.get(p) in kinds]
    groups = sorted({A.group[p] for p in paths})
    ok = [p for p in paths if capper is None or capper.ok(part, A.group[p], total, n_groups or len(groups))]
    if not ok:
        return None
    p = ok[int(rng.integers(len(ok)))]
    if capper:
        capper.use(part, A.group[p])
    return p


# ------------------------------------------------------------------------------------------------- audio helpers

_clip_cache = {}


def clip_audio(path):
    if path not in _clip_cache:
        if len(_clip_cache) > 400:
            _clip_cache.clear()
        _clip_cache[path] = R.load_mono(path)
    return _clip_cache[path]


def fit(x, dur, loop):
    """The clip's active part, looped (rings) or cropped to dur seconds, with 20 ms fades."""
    a, b = R.active_span(x)
    y = x[a:b]
    n = int(round(dur * SR))
    if len(y) < n:
        if not loop:
            n = len(y)
        else:
            reps = int(np.ceil(n / len(y)))
            y = np.concatenate([y] * reps)
    y = y[:n].copy()
    f = min(R.FADE, len(y) // 4)
    if f > 0:
        ramp = np.linspace(0, 1, f, dtype=np.float32)
        y[:f] *= ramp
        y[-f:] *= ramp[::-1]
    return y


def tv_filter(x):
    """Loudspeaker-like band limit (about 150 Hz to 7 kHz) for TV or radio voices."""
    from scipy.signal import butter, sosfilt
    sos = butter(4, [150, 7000], btype="bandpass", fs=SR, output="sos")
    return sosfilt(sos, x).astype(np.float32)


def say(text, voice):
    eng = voice.get("engine", "kokoro")
    return R.tts(text, voice.get("voice"), eng, voice.get("speaker"))


def dur_of(text, voice):
    return len(say(text, voice)) / SR


# ------------------------------------------------------------------------------------------------- unit building

class Timeline:
    def __init__(self):
        self.src, self.assistant, self.points = [], [], []

    def speech(self, sid, text, voice, who, start, pos, rir, db, tv=False):
        d = dur_of(text, voice)
        self.src.append({"id": sid, "kind": "speech", "who": who, "text": text, "voice": voice, "start": round(start, 4),
                         "end": round(start + d, 4), "pos": pos, "rir": rir, "db": round(db, 2), "tv": tv})
        return start + d

    def clip(self, sid, cls, path, start, dur, pos, rir, db, loop=False, kind=None):
        x = fit(clip_audio(path), dur, loop)
        d = len(x) / SR
        self.src.append({"id": sid, "kind": "clip", "cls": cls, "path": path, "start": round(start, 4),
                         "dur": round(dur, 4), "end": round(start + d, 4), "pos": pos, "rir": rir, "db": round(db, 2),
                         "loop": loop, "clip_kind": kind})
        return start + d

    def file(self, sid, path, start, dur, pos, rir, db):
        self.src.append({"id": sid, "kind": "tvfile", "path": path, "start": round(start, 4), "dur": round(dur, 4),
                         "end": round(start + dur, 4), "pos": pos, "rir": rir, "db": round(db, 2)})

    def say_assistant(self, text, start, voice, stop_at=None):
        d = dur_of(text, voice)
        end = start + d if stop_at is None else min(start + d, stop_at)
        self.assistant.append({"text": text, "start": round(start, 4), "end": round(end, 4),
                               "full_end": round(start + d, 4), "voice": voice})
        return start + d

    def speaking(self, t):
        return any(a["start"] <= t < a["end"] for a in self.assistant)

    def point(self, t, kind, gold, line=None, category=None):
        self.points.append({"t": round(t, 4), "kind": kind, "gold": gold, "line": line, "category": category,
                            "assistant_speaking": self.speaking(t - 1e-3)})


def base(rng, A, conv_idx, engine=None):
    room = A.rooms[int(rng.integers(len(A.rooms)))]
    env = A.envs[int(rng.integers(len(A.envs)))]
    if engine == "piper":
        user = {"engine": "piper", "voice": "piper", "speaker": int(A.piper[int(rng.integers(len(A.piper)))])}
    else:
        user = {"engine": "kokoro", "voice": A.voices[int(rng.integers(len(A.voices)))]}
    others = [v for v in A.voices if v != user.get("voice")]
    visitor = {"engine": "kokoro", "voice": others[int(rng.integers(len(others)))]}
    tvv = {"engine": "kokoro", "voice": others[int(rng.integers(len(others)))]}
    return {"conv": conv_idx, "room": room, "noise": f"data/demand_x/{env}/ch01.wav",
            "noise_offset_s": round(float(rng.uniform(0, 240)), 3), "snr_db": round(float(rng.uniform(12, 30)), 2),
            "user": user, "visitor": visitor, "tv_tts": tvv,
            "assistant": {"engine": "piper", "voice": "piper", "speaker": ASSISTANT_PIPER}}


def ulevel(rng, pos):
    return POS_DB[pos] + float(rng.uniform(-1.5, 1.5))


# ---- R-hear (v0.3 F2/F2k with looped rings and group caps)

def plan_r_hear(rng, A, conv_idx, kind, line, total, capper, subset=None, engine=None, ev_paths=None,
                ev_cls=None):
    b = base(rng, A, conv_idx, engine)
    cls = ev_cls or ("phone" if kind == "phone" else ("doorbell" if rng.random() < 0.5 else "knock"))
    d = float(rng.uniform(*DUR[cls]))
    ev = pick_clip(rng, A, cls, f"r_hear:{cls}", total, capper, paths=ev_paths)
    dc = pick_clip(rng, A, "decoy", f"r_hear:decoy", total * 4, capper)
    if ev is None or dc is None:
        return None
    return {**b, "part": "r_hear", "subset": subset, "kind": kind, "line": line, "event": ev, "event_cls": cls,
            "decoy": dc, "decoy_cls": A.decoy_class.get(dc), "dur": round(d, 3),
            "ev_db": round(float(rng.uniform(-8, 4)), 2), "gap": round(float(rng.uniform(0.3, 1.5)), 3),
            "ev_pos": "near" if cls in ("phone", "vibration") and rng.random() < 0.5 else
                      ("across" if cls in ("phone", "vibration") else "door"),
            "user_pos": "near" if rng.random() < 0.7 else "across",
            "after_agent": bool(rng.random() < 0.5), "silence": round(float(rng.uniform(3, 10)), 2),
            "versions": ["1", "2", "3"], "seed": int(rng.integers(2 ** 31))}


def lead_in(spec, t_first_point):
    return max(0.5, WIN + 0.5 - t_first_point)


def build_r_hear(spec, A):
    rng = np.random.default_rng(spec["seed"])
    rir_u, rir_e = A.rir(rng, spec["room"], spec["user_pos"]), A.rir(rng, spec["room"], spec["ev_pos"])
    out = {}
    conv = A.convs[spec["conv"]]
    for v in spec["versions"]:
        tl = Timeline()
        t = 0.0
        if spec["after_agent"]:
            t = tl.speech("req", conv["user_request"], spec["user"], "user", t, spec["user_pos"], rir_u,
                          POS_DB[spec["user_pos"]])
            t = tl.say_assistant(conv["agent_answer"], t + 0.6, spec["assistant"]) + spec["silence"]
        ev_start = t + 0.3
        if v == "1":
            tl.clip("ev", spec["event_cls"], spec["event"], ev_start, spec["dur"], spec["ev_pos"], rir_e,
                    spec["ev_db"], loop=spec["event_cls"] in ("phone", "vibration"))
        elif v == "3":
            tl.clip("ev", "decoy", spec["decoy"], ev_start, spec["dur"], spec["ev_pos"], rir_e, spec["ev_db"])
        line_start = ev_start + spec["dur"] + spec["gap"]
        end = tl.speech("line", spec["line"], spec["user"], "user", line_start, spec["user_pos"], rir_u,
                        POS_DB[spec["user_pos"]])
        gold = {"R": "not" if v == "1" else "respond", "S": None}
        tl.point(end + 0.2, "R", gold, line="line", category="r_hear")
        out[v] = tl
    return shift_all(out, spec)


def shift_all(out, spec):
    """Add the same noise-only lead-in to every version so each first point has 8 s of audio before it."""
    first = min(p["t"] for tl in out.values() for p in tl.points)
    pad = lead_in(spec, first)
    for tl in out.values():
        for s in tl.src:
            s["start"], s["end"] = round(s["start"] + pad, 4), round(s["end"] + pad, 4)
        for a in tl.assistant:
            for k in ("start", "end", "full_end"):
                a[k] = round(a[k] + pad, 4)
        for p in tl.points:
            p["t"] = round(p["t"] + pad, 4)
    spec["lead_in"] = round(pad, 4)
    return out


# ---- R-react: same ring and the same cut, then an answer (1) or a line to the assistant after declining (2)

def plan_r_react(rng, A, conv_idx, kind, total, capper, subset=None, engine=None, ev_paths=None):
    if conv_idx not in A.reject["phone" if kind == "phone" else "door"]:
        return None
    b = base(rng, A, conv_idx, engine)
    rej = A.reject["phone" if kind == "phone" else "door"][conv_idx]
    if kind == "phone":                              # about a third overall (plan 4.2): p = (1/3) / share available
        have = sum("hello_start" in v for v in A.reject["phone"].values()) / max(1, len(A.reject["phone"]))
        use_hello = "hello_start" in rej and rng.random() < min(1.0, (1 / 3) / max(have, 1e-9))
        line2 = rej["hello_start"] if use_hello else rej.get("plain") or rej.get("hello_start")
        if rng.random() < 1 / 3:
            line1 = A.flip["phone"]["common"][int(rng.integers(len(A.flip["phone"]["common"])))]
        else:
            pool = A.pool["phone_answer"]
            line1 = pool[int(rng.integers(len(pool)))]["line"]
        cls = "phone"
    else:
        line2 = rej["plain"]
        cls = "doorbell" if rng.random() < 0.5 else "knock"
        if rng.random() < 1 / 3:
            line1 = A.flip["door"]["common"][int(rng.integers(len(A.flip["door"]["common"])))]
        else:
            pool = [p for p in A.pool["door_answer"] if p["event"] == cls] or A.pool["door_answer"]
            line1 = pool[int(rng.integers(len(pool)))]["line"]
    ev = pick_clip(rng, A, cls, f"r_react:{cls}", total, capper, paths=ev_paths)
    if ev is None:
        return None
    ring = float(rng.uniform(2.0, 5.0)) if cls == "phone" else float(rng.uniform(*DUR[cls]))
    return {**b, "part": "r_react", "subset": subset, "kind": kind, "event": ev, "event_cls": cls, "ring": round(ring, 3),
            "ev_db": round(float(rng.uniform(-8, 4)), 2), "gap": round(float(rng.uniform(0.3, 0.9)), 3),
            "ev_pos": ("near" if rng.random() < 0.5 else "across") if cls == "phone" else "door",
            "user_pos": "near" if rng.random() < 0.7 else "across", "line1": line1, "line2": line2,
            "line2_hello": kind == "phone" and line2 == rej.get("hello_start"),
            "silence": round(float(rng.uniform(1.5, 6)), 2), "versions": ["1", "2"], "seed": int(rng.integers(2 ** 31))}


def build_r_react(spec, A):
    rng = np.random.default_rng(spec["seed"])
    rir_u, rir_e = A.rir(rng, spec["room"], spec["user_pos"]), A.rir(rng, spec["room"], spec["ev_pos"])
    conv = A.convs[spec["conv"]]
    out = {}
    for v in spec["versions"]:
        tl = Timeline()
        t = tl.speech("req", conv["user_request"], spec["user"], "user", 0.0, spec["user_pos"], rir_u,
                      POS_DB[spec["user_pos"]])
        t = tl.say_assistant(conv["agent_answer"], t + 0.6, spec["assistant"]) + spec["silence"]
        t = tl.clip("ev", spec["event_cls"], spec["event"], t, spec["ring"], spec["ev_pos"], rir_e, spec["ev_db"],
                    loop=spec["event_cls"] == "phone")
        line = spec["line1"] if v == "1" else spec["line2"]
        end = tl.speech("line", line, spec["user"], "user", t + spec["gap"], spec["user_pos"], rir_u,
                        POS_DB[spec["user_pos"]])
        tl.point(end + 0.2, "R", {"R": "not" if v == "1" else "respond", "S": None}, line="line", category="r_react")
        out[v] = tl
    return shift_all(out, spec)


# ---- S-react: the assistant is talking; the same event; answer (1), keep going (2), backchannel (3), silent (4)

def plan_s_react(rng, A, conv_idx, kind, total, capper, subset=None, engine=None, ev_paths=None, echo=False):
    b = base(rng, A, conv_idx, engine)
    if kind == "phone":
        cls = "phone"
        line1 = (A.flip["phone"]["common"][int(rng.integers(len(A.flip["phone"]["common"])))] if rng.random() < 1 / 3
                 else A.pool["phone_answer"][int(rng.integers(len(A.pool["phone_answer"])))]["line"])
        kg = [p for p in A.pool["keep_going"] if p["event"] == "phone"]
    else:
        cls = "doorbell" if rng.random() < 0.5 else "knock"
        pool = [p for p in A.pool["door_answer"] if p["event"] == cls] or A.pool["door_answer"]
        line1 = (A.flip["door"]["common"][int(rng.integers(len(A.flip["door"]["common"])))] if rng.random() < 1 / 3
                 else pool[int(rng.integers(len(pool)))]["line"])
        kg = [p for p in A.pool["keep_going"] if p["event"] == cls]
    kg = kg or A.pool["keep_going"]
    ev = pick_clip(rng, A, cls, f"s_react:{cls}", total, capper, paths=ev_paths)
    if ev is None:
        return None
    return {**b, "part": "s_react", "subset": subset, "kind": kind, "event": ev, "event_cls": cls, "echo": echo,
            "ev_db": round(float(rng.uniform(-8, 4)), 2), "ev_after": round(float(rng.uniform(0.6, 2.0)), 3),
            "ring": round(float(rng.uniform(1.5, 3.5)), 3) if cls == "phone" else round(float(rng.uniform(*DUR[cls])), 3),
            "ring_long": round(float(rng.uniform(15, 30)), 2), "gap": round(float(rng.uniform(0.3, 0.8)), 3),
            "ev_pos": ("near" if rng.random() < 0.5 else "across") if cls == "phone" else "door",
            "user_pos": "near" if rng.random() < 0.7 else "across",
            "line1": line1, "line2": kg[int(rng.integers(len(kg)))]["line"],
            "line3": A.backchannel[int(rng.integers(len(A.backchannel)))],
            "cut23": bool(rng.random() < 0.5), "echo_db": round(float(rng.uniform(-35, -25)), 2),
            "versions": ["1", "2", "3", "4"], "seed": int(rng.integers(2 ** 31))}


def build_s_react(spec, A):
    rng = np.random.default_rng(spec["seed"])
    rir_u, rir_e = A.rir(rng, spec["room"], spec["user_pos"]), A.rir(rng, spec["room"], spec["ev_pos"])
    conv = A.convs[spec["conv"]]
    phone = spec["event_cls"] == "phone"
    out, t_dec1 = {}, None
    for v in ["1", "2", "3", "4"]:
        tl = Timeline()
        t = tl.speech("req", conv["user_request"], spec["user"], "user", 0.0, spec["user_pos"], rir_u,
                      POS_DB[spec["user_pos"]])
        a0 = t + 0.6
        a_end = tl.say_assistant(conv["agent_answer"], a0, spec["assistant"])
        ev0 = a0 + spec["ev_after"]
        cut = ev0 + spec["ring"]
        rings_on = phone and (v == "4" or (v in ("2", "3") and not spec["cut23"]))
        dur = spec["ring_long"] if rings_on else spec["ring"]
        tl.clip("ev", spec["event_cls"], spec["event"], ev0, dur, spec["ev_pos"], rir_e, spec["ev_db"], loop=phone)
        line_start = cut + spec["gap"]
        if v != "4":
            line = spec[f"line{v}"]
            end = tl.speech("line", line, spec["user"], "user", line_start, spec["user_pos"], rir_u,
                            POS_DB[spec["user_pos"]])
            t_dec = end + 0.2
            if v == "1":
                t_dec1 = t_dec
                tl.assistant[-1]["end"] = round(min(tl.assistant[-1]["full_end"], t_dec), 4)
                tl.point(t_dec, "RS", {"S": "stop", "R": "not"}, line="line", category="s_react")
            else:
                tl.point(t_dec, "RS", {"S": "continue", "R": None}, line="line", category="s_react")
        else:
            tl.point(t_dec1, "S", {"S": "continue", "R": None}, category="s_react")
        if spec.get("echo"):
            tl.src.append({"id": "echo", "kind": "echo", "start": round(a0, 4), "end": round(tl.assistant[-1]["end"], 4),
                           "pos": "near", "rir": rir_u, "db": spec["echo_db"]})
        out[v] = tl
        if v == "1" and t_dec1 > a_end - 0.3:
            return None                                       # the assistant would have finished: redraw
    return shift_all(out, spec)


# ---- S-move: door only; the assistant is talking; the user is silent

def plan_s_move(rng, A, conv_idx, total, capper, subset=None, engine=None, ev_paths=None, door_source="fsd50k",
                echo=False):
    b = base(rng, A, conv_idx, engine)
    cls = "doorbell" if rng.random() < 0.5 else "knock"
    ev = pick_clip(rng, A, cls, f"s_move:{cls}", total, capper, paths=ev_paths)
    steps = pick_clip(rng, A, "footsteps", "s_move:footsteps", total, capper)
    doors = A.new["door"] if door_source == "freesound" else A.clips.get("door", [])
    door = pick_clip(rng, A, "door", f"s_move:door_{door_source}", total, capper, paths=doors,
                     kinds={"open", "unknown", "both"})
    cab = pick_clip(rng, A, "cabinet", "s_move:cabinet", total, capper)
    tvs = A.tv_plan
    if None in (ev, steps, door, cab) or not tvs:
        return None
    tv_real = bool(rng.random() < 0.5)
    conv = A.convs[conv_idx]
    tv_text = None
    if not tv_real:
        other = A.convs[int(rng.integers(len(A.convs)))]
        tv_text = other["agent_answer"]
    n_steps = int(rng.integers(3, 5))
    return {**b, "part": "s_move", "subset": subset, "event": ev, "event_cls": cls, "steps": steps, "door": door,
            "door_source": door_source, "cabinet": cab, "echo": echo, "echo_db": round(float(rng.uniform(-35, -25)), 2),
            "tv_real": tv_real, "tv_file": tvs[int(rng.integers(len(tvs)))] if tv_real else None, "tv_text": tv_text,
            "ev_db": round(float(rng.uniform(-8, 4)), 2), "ev_after": round(float(rng.uniform(0.6, 2.0)), 3),
            "ev_dur": round(float(rng.uniform(*DUR[cls])), 3), "walk_after": round(float(rng.uniform(1.0, 2.5)), 3),
            "n_steps": n_steps, "step_dur": [round(float(rng.uniform(0.6, 1.0)), 3) for _ in range(n_steps)],
            "step_db": round(float(rng.uniform(-14, -4)), 2), "door_gap": round(float(rng.uniform(0.2, 0.6)), 3),
            "door_dur": round(float(rng.uniform(0.6, 1.5)), 3), "door_db": round(float(rng.uniform(-10, 0)), 2),
            "visitor_speaks": bool(rng.random() < 0.5), "visitor_after": round(float(rng.uniform(0.2, 0.6)), 3),
            "visitor_line": None, "tv_db": round(float(rng.uniform(-20, -5)), 2),
            "versions": ["1", "2", "3", "4"], "seed": int(rng.integers(2 ** 31))}


VISITOR_OPENERS = ["Hi, I've got a parcel here for you.", "Hello! Sorry to bother you, I'm from next door.",
                   "Hi there, delivery for this address.", "Hey, it's me, I brought your dish back.",
                   "Good afternoon, I'm here about the boiler.", "Hi, is this flat four?"]


def build_s_move(spec, A):
    rng = np.random.default_rng(spec["seed"])
    room = spec["room"]
    rir_e = A.rir(rng, room, "door")
    walk = A.walk(rng, room, spec["n_steps"], away=True)
    rir_far = A.rir(rng, room, "door")
    rir_tv = A.rir(rng, room, "across")
    conv = A.convs[spec["conv"]]
    vline = VISITOR_OPENERS[int(rng.integers(len(VISITOR_OPENERS)))]
    out, t_dec = {}, None
    for v in ["1", "2", "3", "4"]:
        tl = Timeline()
        t = tl.speech("req", conv["user_request"], spec["user"], "user", 0.0, "near", A.rir(np.random.default_rng(
            spec["seed"] + 1), room, "near"), 0.0)
        a0 = t + 0.6
        a_end = tl.say_assistant(conv["agent_answer"], a0, spec["assistant"])
        ev0 = a0 + spec["ev_after"]
        if v in ("1", "2"):
            tl.clip("ev", spec["event_cls"], spec["event"], ev0, spec["ev_dur"], "door", rir_e, spec["ev_db"])
        ts = ev0 + spec["ev_dur"] + spec["walk_after"]
        x = fit(clip_audio(spec["steps"]), sum(spec["step_dur"]) + 0.1, loop=True)
        off = 0.0
        for k, (d, rir) in enumerate(zip(spec["step_dur"], walk)):
            if v in ("1", "3"):
                tl.src.append({"id": f"step{k}", "kind": "clip", "cls": "footsteps", "path": spec["steps"],
                               "start": round(ts, 4), "dur": round(d, 4), "end": round(ts + d, 4), "pos": f"walk{k}",
                               "rir": rir, "db": spec["step_db"], "loop": True, "seg_offset": round(off, 4)})
            ts += d
            off += d
        td = ts + spec["door_gap"]
        if v == "1":
            tl.clip("door", "door", spec["door"], td, spec["door_dur"], "door", rir_far, spec["door_db"],
                    kind=A.kind.get(spec["door"]))
            if spec["visitor_speaks"]:
                tl.speech("visitor", vline, spec["visitor"], "visitor", td + spec["visitor_after"], "door", rir_far,
                          POS_DB["door"])
        if v == "3":
            tl.clip("door", "cabinet", spec["cabinet"], td, spec["door_dur"], "door", rir_far, spec["door_db"],
                    kind=A.kind.get(spec["cabinet"]))
        t_dec = td + 1.0
        if v == "4":                                    # after the request, so the history is identical
            start = a0 + 0.3
            length = t_dec - start + 0.5
            if spec["tv_real"]:
                tl.file("tv", spec["tv_file"], start, length, "across", rir_tv, spec["tv_db"])
            else:
                tl.speech("tv", spec["tv_text"], spec["tv_tts"], "tv", start, "across", rir_tv, spec["tv_db"], tv=True)
        if v == "1":
            tl.assistant[-1]["end"] = round(min(tl.assistant[-1]["full_end"], t_dec), 4)
        if spec.get("echo"):
            tl.src.append({"id": "echo", "kind": "echo", "start": round(a0, 4), "end": round(tl.assistant[-1]["end"], 4),
                           "pos": "near", "rir": A.rir(np.random.default_rng(spec["seed"] + 2), room, "near"),
                           "db": spec["echo_db"]})
        tl.point(t_dec, "S", {"S": "stop" if v == "1" else "continue", "R": None}, category="s_move")
        out[v] = tl
        if t_dec > a_end - 0.3:
            return None
    spec["visitor_line"] = vline
    return shift_all(out, spec)


# ------------------------------------------------------------------------------------------------- rendering

def source_audio(s, A, spec):
    if s["kind"] == "speech":
        x = say(s["text"], s["voice"])
        if s.get("tv"):
            x = tv_filter(x)
    elif s["kind"] == "clip":
        x = fit(clip_audio(s["path"]), s.get("dur", 10.0) + s.get("seg_offset", 0.0), s.get("loop", False))
        if "seg_offset" in s:                          # one footstep segment, 10 ms fades at its own edges
            o = int(round(s["seg_offset"] * SR))
            x = x[o:o + int(round(s["dur"] * SR))].copy()
            f = min(int(0.01 * SR), len(x) // 4)
            if f > 0:
                ramp = np.linspace(0, 1, f, dtype=np.float32)
                x[:f] *= ramp
                x[-f:] *= ramp[::-1]
    elif s["kind"] == "tvfile":
        y = R.load_mono(s["path"])
        n = int(round(s["dur"] * SR))
        y = np.concatenate([y] * int(np.ceil(n / max(1, len(y)))))[:n] if len(y) < n else y[:n]
        x = tv_filter(y)
    elif s["kind"] == "echo":
        a = spec["_assistant_text"]
        x = say(a, spec["assistant"])[:int(round((s["end"] - s["start"]) * SR))]
    else:
        raise ValueError(s["kind"])
    return R.at_level(R.reverb(x, s["rir"]), R.REF * 10 ** (s["db"] / 20))


def render_versions(spec, tls, A):
    """{version: int16 audio}, spans, peak; identity check outside the spans of differing sources."""
    total = max(max([s["end"] for s in tl.src] + [p["t"] for p in tl.points] + [a["end"] for a in tl.assistant])
                for tl in tls.values()) + 1.5
    n = int(np.ceil(total * SR))
    noise = R.noise_segment(spec["noise"], spec["noise_offset_s"], n)
    if len(noise) < n:
        noise = np.concatenate([noise] * int(np.ceil(n / max(1, len(noise)))))[:n]
    noise = noise * ((R.REF / 10 ** (spec["snr_db"] / 20)) / (np.sqrt((noise ** 2).mean()) + 1e-9))
    spec["_assistant_text"] = A.convs[spec["conv"]]["agent_answer"] if "conv" in spec else ""
    cache, mixes, wet_end = {}, {}, {}
    for v, tl in tls.items():
        buf = noise.astype(np.float32).copy()
        for s in tl.src:
            key = json.dumps({k: s[k] for k in sorted(s) if k not in ("id",)}, sort_keys=True, default=str)
            if key not in cache:
                cache[key] = source_audio(s, A, spec)
            w = cache[key]
            a, b = R.place(buf, w, int(round(s["start"] * SR)))
            wet_end[(v, s["id"])] = b / SR
        mixes[v] = buf
    peak = max(float(np.abs(m).max()) for m in mixes.values())
    scale = 0.98 / peak if peak > 0.98 else 1.0
    out = {v: np.round(np.clip(m * scale, -1, 1) * 32767).astype(np.int16) for v, m in mixes.items()}
    vs = list(out)
    if len(vs) > 1:
        sig = {v: {s["id"]: json.dumps({k: s[k] for k in sorted(s)}, sort_keys=True, default=str) for s in tls[v].src}
               for v in vs}
        for v in vs[1:]:
            d = np.abs(out[v].astype(np.int32) - out[vs[0]].astype(np.int32))
            for ver in (vs[0], v):
                for s in tls[ver].src:
                    other = vs[0] if ver == v else v
                    if sig[other].get(s["id"]) != sig[ver][s["id"]]:
                        d[int(s["start"] * SR):int(np.ceil(wet_end[(ver, s["id"])] * SR)) + 1] = 0
            assert d.max() <= 1, f"{spec.get('unit')}: version {v} differs from {vs[0]} outside the differing spans"
    return out, round(20 * np.log10(scale), 2) if scale < 1 else 0.0


def windows(audio, points):
    res = []
    for p in points:
        e = int(round(p["t"] * SR))
        s = e - int(WIN * SR)
        assert s >= 0, "window starts before the unit"
        res.append(audio[s:e])
    return res


# ---- floors (plan 4.6) and report-only cells (plan 4.8)

BARGE_OPENERS = ["Wait, ", "Sorry, ", "Hang on, "]     # half of the barge-in checks open the follow-up with one


def plan_floor(rng, A, conv_idx, which, total, capper):
    """which: D, Dk (silent assistant; the event starts while the user asks and is ignored), HE (silent; event, then
    a line to the assistant about it), HS (the same while the assistant talks), barge (talking; no event; a question),
    quiet (talking; no event; nobody speaks; a probe)."""
    b = base(rng, A, conv_idx)
    conv = A.convs[conv_idx]
    cls = None
    if which in ("D", "HE_phone", "HS_phone"):
        cls = "phone"
    elif which in ("Dk", "HE_door", "HS_door"):
        cls = "doorbell" if rng.random() < 0.5 else "knock"
    ev = pick_clip(rng, A, cls, f"floor:{cls}", total, capper) if cls else None
    if cls and ev is None:
        return None
    line = None
    if which in ("D", "Dk", "barge"):
        line = conv["user_followup"]
        if which == "barge" and rng.random() < 0.5:
            line = BARGE_OPENERS[int(rng.integers(3))] + line[0].lower() + line[1:]
    elif which.startswith(("HE", "HS")):
        pool = A.v3lines["he_phone" if cls == "phone" else "he_door"]
        line = pool[int(rng.integers(len(pool)))]
    return {**b, "part": "floor", "which": which, "event": ev, "event_cls": cls, "line": line,
            "ev_db": round(float(rng.uniform(-8, 4)), 2),
            "dur": round(float(rng.uniform(*DUR[cls])), 3) if cls else None,
            "onset_frac": round(float(rng.uniform(0.2, 0.7)), 3), "gap": round(float(rng.uniform(0.3, 1.5)), 3),
            "ev_pos": ("near" if rng.random() < 0.5 else "across") if cls == "phone" else "door",
            "user_pos": "near" if rng.random() < 0.7 else "across", "silence": round(float(rng.uniform(1.5, 6)), 2),
            "ev_after": round(float(rng.uniform(0.6, 2.0)), 3), "probe_after": round(float(rng.uniform(2.0, 6.0)), 3),
            "versions": ["1"], "seed": int(rng.integers(2 ** 31))}


def build_floor(spec, A):
    rng = np.random.default_rng(spec["seed"])
    rir_u, rir_e = A.rir(rng, spec["room"], spec["user_pos"]), A.rir(rng, spec["room"], spec["ev_pos"])
    conv = A.convs[spec["conv"]]
    w = spec["which"]
    tl = Timeline()
    t = tl.speech("req", conv["user_request"], spec["user"], "user", 0.0, spec["user_pos"], rir_u,
                  POS_DB[spec["user_pos"]])
    a0 = t + 0.6
    talking = w.startswith("HS") or w in ("barge", "quiet")
    a_end = tl.say_assistant(conv["agent_answer"], a0, spec["assistant"])
    if not talking:
        t = a_end + spec["silence"]
        if w in ("D", "Dk"):
            d = dur_of(spec["line"], spec["user"])
            tl.clip("ev", spec["event_cls"], spec["event"], t + spec["onset_frac"] * d, spec["dur"], spec["ev_pos"],
                    rir_e, spec["ev_db"], loop=spec["event_cls"] == "phone")
            end = tl.speech("line", spec["line"], spec["user"], "user", t, spec["user_pos"], rir_u,
                            POS_DB[spec["user_pos"]])
        else:
            te = tl.clip("ev", spec["event_cls"], spec["event"], t, spec["dur"], spec["ev_pos"], rir_e, spec["ev_db"],
                         loop=spec["event_cls"] == "phone")
            end = tl.speech("line", spec["line"], spec["user"], "user", t + spec["dur"] + spec["gap"],
                            spec["user_pos"], rir_u, POS_DB[spec["user_pos"]])
        tl.point(end + 0.2, "R", {"R": "respond", "S": None}, line="line", category=f"floor_{w}")
    elif w == "quiet":
        tp = a0 + spec["probe_after"]
        if tp > a_end - 0.3:
            return None
        tl.point(tp, "S", {"S": "continue", "R": None}, category="floor_quiet")
    else:
        ts = a0 + spec["ev_after"]
        if w.startswith("HS"):
            tl.clip("ev", spec["event_cls"], spec["event"], ts, spec["dur"], spec["ev_pos"], rir_e, spec["ev_db"],
                    loop=spec["event_cls"] == "phone")
            ts += spec["dur"] + spec["gap"]
        end = tl.speech("line", spec["line"], spec["user"], "user", ts, spec["user_pos"], rir_u,
                        POS_DB[spec["user_pos"]])
        if end + 0.2 > a_end - 0.3:
            return None
        tl.assistant[-1]["end"] = round(end + 0.2, 4)
        tl.point(end + 0.2, "RS", {"S": "stop", "R": "respond"}, line="line", category=f"floor_{w}")
    return shift_all({"1": tl}, spec)


def plan_report(rng, A, conv_idx, which, total, capper):
    """F3 (a family member calls from another room; version 1: the reply to them, not respond; version 2: the same
    reply with no call, respond) and B2 (the user turns to another person in the room: not respond)."""
    b = base(rng, A, conv_idx)
    if which == "F3":
        fam, rep = (lambda p: (p["family_call"], p["user_reply"]))(A.v3lines["f3_pair"][int(rng.integers(
            len(A.v3lines["f3_pair"])))])
        return {**b, "part": "report", "which": "F3", "family_call": fam, "line": rep, "versions": ["1", "2"],
                "gap": round(float(rng.uniform(0.3, 1.2)), 3), "silence": round(float(rng.uniform(1.5, 6)), 2),
                "user_pos": "near" if rng.random() < 0.7 else "across", "seed": int(rng.integers(2 ** 31))}
    line = A.v3lines["b2_side"][int(rng.integers(len(A.v3lines["b2_side"])))]
    return {**b, "part": "report", "which": "B2", "line": line, "versions": ["1"],
            "silence": round(float(rng.uniform(1.5, 6)), 2), "user_pos": "near" if rng.random() < 0.7 else "across",
            "seed": int(rng.integers(2 ** 31))}


def build_report(spec, A):
    rng = np.random.default_rng(spec["seed"])
    rir_u, rir_f = A.rir(rng, spec["room"], spec["user_pos"]), A.rir(rng, spec["room"], "door")
    conv = A.convs[spec["conv"]]
    out = {}
    for v in spec["versions"]:
        tl = Timeline()
        t = tl.speech("req", conv["user_request"], spec["user"], "user", 0.0, spec["user_pos"], rir_u,
                      POS_DB[spec["user_pos"]])
        t = tl.say_assistant(conv["agent_answer"], t + 0.6, spec["assistant"]) + spec["silence"]
        if spec["which"] == "F3":
            fam_len = dur_of(spec["family_call"], spec["visitor"])
            if v == "1":
                tl.speech("family", spec["family_call"], spec["visitor"], "family", t, "door", rir_f, -6.0)
            t += fam_len + spec["gap"]
            gold = "not" if v == "1" else "respond"
        else:
            gold = "not"
        end = tl.speech("line", spec["line"], spec["user"], "user", t, spec["user_pos"], rir_u,
                        POS_DB[spec["user_pos"]])
        tl.point(end + 0.2, "R", {"R": gold, "S": None}, line="line", category=f"report_{spec['which']}")
        out[v] = tl
    return shift_all(out, spec)


# ---- episodes (plan 4.5): the checked script scheduled in time

P_CALL_FAR, P_ASST_FAR = 0.5, 0.35             # far positions balanced between "respond" and "not" (shortcut check)
EV_SOUNDS = ("phone_ring", "doorbell", "knock")


def episode_clip_needs(turns):
    """The recordings an episode script uses (only these are picked and counted against the caps)."""
    snd = {t["sound"] for t in turns if t["kind"] == "sound"}
    return {k for k, s in (("ring", {"phone_ring"}), ("door_event", {"doorbell", "knock"}),
                           ("steps", {"footsteps_away", "footsteps_back"}), ("door_open", {"door_open"}),
                           ("door_close", {"door_close"})) if snd & s}


def episode_door_event(gen, turns):
    """The door sound the script names (it always matches the plan's door_event), else the plan's, else None."""
    return next((t["sound"] for t in turns if t["kind"] == "sound" and t["sound"] in ("doorbell", "knock")),
                gen.get("door_event"))


def episode_cap_keys(gen, turns, door_source):
    """Cap keys (pick_clip's part argument) an episode uses; the planner's totals count episodes per key, the share
    the leak check measures (units that use a recording type)."""
    need = episode_clip_needs(turns)
    keys = set()
    if "ring" in need:
        keys.add("episode:phone")
    if "door_event" in need:
        keys.add(f"episode:{episode_door_event(gen, turns)}")
    if "steps" in need:
        keys.add("episode:footsteps")
    if "door_open" in need:
        keys.add(f"episode:door_open_{door_source}")
    if "door_close" in need:
        keys.add(f"episode:door_close_{door_source}")
    return keys


def plan_episode(rng, A, gen, turns, totals, capper, door_source="fsd50k", engine=None, subset=None):
    """Voices, room, levels and the recordings the script uses. totals: {cap key: number of episodes of this split
    that use it}; a failed pick leaves its uses in capper.log for the caller to release."""
    b = base(rng, A, gen["conv"], engine)
    part = "episode"
    need = episode_clip_needs(turns)
    door_ev = episode_door_event(gen, turns) or ("doorbell" if rng.random() < 0.5 else "knock")
    doors = A.new["door"] if door_source == "freesound" else A.clips.get("door", [])
    okey, ckey = f"{part}:door_open_{door_source}", f"{part}:door_close_{door_source}"
    clips = {}
    if "ring" in need:
        clips["ring"] = pick_clip(rng, A, "phone", f"{part}:phone", totals.get(f"{part}:phone", 1), capper)
    if "door_event" in need:
        clips["door_event"] = pick_clip(rng, A, door_ev, f"{part}:{door_ev}", totals.get(f"{part}:{door_ev}", 1),
                                        capper)
    if "steps" in need:
        clips["steps"] = pick_clip(rng, A, "footsteps", f"{part}:footsteps", totals.get(f"{part}:footsteps", 1),
                                   capper)
    # Opening and closing sounds are capped as two recording types (plan 5.6: each type separately); the closing clip
    # comes from the opening clip's group (the same door) when that group is under the closing cap.
    opening, closing = {"open", "unknown", "both"}, {"close", "unknown", "both"}
    if "door_open" in need:
        clips["door_open"] = pick_clip(rng, A, "door", okey, totals.get(okey, 1), capper, paths=doors, kinds=opening)
    if "door_close" in need:
        n_close = len({A.group[p] for p in doors if A.kind.get(p) in closing})
        same = [p for p in doors if clips.get("door_open") and A.group[p] == A.group[clips["door_open"]]]
        pick = pick_clip(rng, A, "door", ckey, totals.get(ckey, 1), capper, paths=same, kinds=closing,
                         n_groups=n_close) if same else None
        clips["door_close"] = pick or pick_clip(rng, A, "door", ckey, totals.get(ckey, 1), capper, paths=doors,
                                                kinds=closing)
    if None in clips.values():
        return None
    return {**b, "part": part, "subset": subset, "episode": gen["episode"], "etype": gen["type"],
            "during": bool(gen.get("during")), "silent": bool(gen.get("silent")), "how": gen.get("how"),
            "door_event_cls": door_ev, "door_source": door_source, "clips": clips, "turns": turns,
            "call_pos": "across" if rng.random() < P_CALL_FAR else "near",
            "ev_db": round(float(rng.uniform(-8, 4)), 2), "step_db": round(float(rng.uniform(-14, -4)), 2),
            "door_db": round(float(rng.uniform(-10, 0)), 2), "versions": ["1"], "seed": int(rng.integers(2 ** 31))}


def episode_points_expected(spec):
    """The script's decision points in order (the same rules as the text check in step0v4_episodes.py)."""
    import step0v4_episodes as E
    plan = {"type": spec["etype"], "during": spec["during"], "silent": spec["silent"]}
    return [(None if k == "probe_S" else i, k, g.get("S"), g.get("R")) for i, k, g in E.points(plan, spec["turns"])]


def build_episode(spec, A, attempts=20):
    """Timeline of one episode script, kept in the script's order (the text check reads the script in that order).
    Items the script marks as overlapping the assistant, and in an episode whose event happens while the assistant
    talks everything from the event to the person's first reaction, are placed inside the assistant's turn after the
    item before them; every other item waits until the assistant has finished or was cut. An ignored event gets its S
    probe at a door-going time after it starts (door_going_delay), before anything else is heard; a silent door-going
    gets its probe 1 s after the door opens, before the visitor speaks. Built timelines must give the script's
    decision points (kind and gold, in order) and start every item no earlier than the item before it in the script;
    otherwise the next seed is tried, and the episode is dropped (None) when no seed out of `attempts` fits."""
    want = episode_points_expected(spec)
    for attempt in range(attempts):
        tl, placed = _episode_timeline(spec, A, np.random.default_rng([spec["seed"], attempt]))
        got = [(int(p["line"][1:]) if p["line"] else None, "probe_S" if p["line"] is None else p["kind"],
                p["gold"].get("S"), p["gold"].get("R")) for p in sorted(tl.points, key=lambda p: p["t"])]
        times = [x for _, x in sorted(placed, key=lambda z: z[0])]
        if got == want and all(b >= a - 1e-6 for a, b in zip(times, times[1:])):
            spec["build_attempt"] = attempt
            spec["during_s_point"] = bool(spec["during"]) and any(p["kind"] in ("S", "RS") for p in tl.points)
            return shift_all({"1": tl}, spec)
    return None


def door_going_delay(rng, cls):
    """Seconds from the start of a door sound to the silent door-going probe, drawn as _episode_timeline places them:
    the sound (DUR), a pause before walking (1.0-2.5 s), 3-4 steps of 0.6-1.0 s, 0.2-0.6 s to the door, then 1 s after
    the door opens. The ignored-event probe uses the same draw (for a phone ring, the door sound of the episode's plan),
    so the time since the event does not tell the silent stop from the silent continue (plan 8.3; 2026-11-14)."""
    d = rng.uniform(*DUR[cls]) + rng.uniform(1.0, 2.5)
    d += sum(rng.uniform(0.6, 1.0) for _ in range(int(rng.integers(3, 5))))
    return d + rng.uniform(0.2, 0.6) + 1.0


def _episode_timeline(spec, A, rng):
    room, turns = spec["room"], spec["turns"]
    rirs = {p: A.rir(rng, room, p) for p in ("near", "across", "door")}
    tl = Timeline()
    U = lambda a, b: float(rng.uniform(a, b))                                   # noqa: E731
    t, at_door, in_call, in_turn = 0.0, False, False, False   # in_turn: placing items inside the assistant's turn
    ring = None                                    # pending ring: {"start", "ignored"}
    first_event, first_reaction_done, n_user = None, False, 0
    placed = []                                    # (script index, start) of every item; probes at index + 0.5
    away_seen, last_away_idx = False, max([i for i, x in enumerate(turns) if x["kind"] == "speech" and
                                           x["speaker"] == "user" and x["addressee"] in ("caller", "visitor")],
                                          default=-1)

    def busy():                                    # the assistant talks until this time (its cut or its full end)
        return tl.assistant[-1]["end"] if tl.assistant else 0.0

    def free():                                    # where the next sound or visitor line can start
        return t if in_turn and busy() > t else max(t, busy())

    def add_ring(end):
        tl.clip("ring", "phone", spec["clips"]["ring"], ring["start"], max(1.0, end - ring["start"]),
                "near" if spec["call_pos"] == "near" else "across", rirs[spec["call_pos"]], spec["ev_db"], loop=True)

    def steps(away):
        nonlocal t
        n = int(rng.integers(3, 5))
        walk = A.walk(rng, room, n, away=away)
        off = 0.0
        for k, rir in enumerate(walk):
            d = U(0.6, 1.0)
            tl.src.append({"id": f"st{len(tl.src)}", "kind": "clip", "cls": "footsteps", "path": spec["clips"]["steps"],
                           "start": round(t, 4), "dur": round(d, 4), "end": round(t + d, 4), "pos": f"walk{k}",
                           "rir": rir, "db": spec["step_db"], "loop": True, "seg_offset": round(off, 4)})
            t += d
            off += d

    for i, tu in enumerate(turns):
        last_a = tl.assistant[-1] if tl.assistant else None
        if tu["kind"] == "speech" and tu["speaker"] == "assistant":
            start = max(t, busy()) + U(0.3, 0.9)
            placed.append((i, start))
            tl.say_assistant(tu["text"], start, spec["assistant"])
            t, in_turn = start, False
            continue
        if tu["kind"] == "speech" and tu["speaker"] == "visitor":
            start = free() + U(0.3, 1.0)
            placed.append((i, start))
            t = tl.speech(f"v{i}", tu["text"], spec["visitor"], "visitor", start, "door", rirs["door"], POS_DB["door"])
            continue
        if tu["kind"] == "pause":
            t = free() + (U(2.0, 6.0) if tu["pause"] == "listening" else U(0.5, 1.5))
            continue
        if tu["kind"] == "sound":
            s = tu["sound"]
            if s in EV_SOUNDS:
                in_t = last_a is not None and (tu["overlaps_assistant"] or (spec["during"] and first_event is None))
                start = max(t + U(0.3, 0.8), last_a["start"] + U(0.6, 2.0)) if in_t else max(t, busy()) + U(0.5, 1.5)
                first_event = first_event if first_event is not None else start
                placed.append((i, start))
                if s == "phone_ring":
                    ring = {"start": start, "ignored": spec.get("how") == "rings_out"}
                    t = start + (U(1.5, 3.0) if ring["ignored"] else U(1.5, 3.5))
                else:
                    t = tl.clip("dev", s, spec["clips"]["door_event"], start, U(*DUR[s]), "door", rirs["door"],
                                spec["ev_db"])
                in_turn = in_t
                if spec["etype"] == "ignored" and spec["during"] and in_t:
                    tp = start + door_going_delay(np.random.default_rng(int(rng.integers(2 ** 31))),
                                                  s if s in DUR else spec["door_event_cls"])
                    if tp < busy() - 0.3:
                        tl.point(tp, "S", {"S": "continue", "R": None}, category="stop_or_not")
                        placed.append((i + 0.5, tp))
                        t = max(t, tp + U(0.2, 0.5))
            elif s == "ring_stops":
                if ring:
                    # plan 3.2: a ring left to ring out lasts about 15-30 s
                    stop = max(free(), ring["start"] + (U(15.0, 30.0) if ring["ignored"] else 1.0))
                    add_ring(stop)
                    ring = None
                    placed.append((i, stop))
                    t = stop
            elif s == "footsteps_away":
                t = free()
                t += U(1.0, 2.5) if first_event is not None and t - first_event < 3 else U(0.3, 1.0)
                placed.append((i, t))
                steps(True)
                at_door = True
            elif s == "footsteps_back":
                t = free()
                placed.append((i, t))
                steps(False)
                at_door = False
            elif s in ("door_open", "door_close"):
                start = free() + U(0.2, 0.6)
                clip = spec["clips"][s]
                placed.append((i, start))
                t = tl.clip(f"door{i}", "door", clip, start, U(0.6, 1.5), "door", rirs["door"], spec["door_db"],
                            kind=A.kind.get(clip))
                tl.src[-1]["role"] = s
                if s == "door_open" and spec["etype"] == "visitor" and spec["silent"] and spec["during"] \
                        and not first_reaction_done and last_a is not None:
                    tp = start + 1.0
                    if tp < busy() - 0.3:
                        last_a["end"] = round(tp, 4)
                        tl.point(tp, "S", {"S": "stop", "R": None}, category="stop_or_not")
                        placed.append((i + 0.5, tp))
                        t = max(t, tp + U(0.1, 0.4))
                    first_reaction_done = True
            continue
        # user line
        n_user += 1
        to_a = tu["addressee"] == "assistant"
        first_after_event = (spec["during"] and first_event is not None and not first_reaction_done
                             and spec["etype"] in ("phone", "visitor", "short"))
        overl = tu["act"] in ("backchannel", "keep_going") or tu["overlaps_assistant"] or first_after_event
        if ring and tu["addressee"] == "caller":                    # picked up: the ring stops just before
            gap = U(0.3, 0.8)
            start = max(ring["start"] + 1.0 + gap, t + gap)
            add_ring(start - gap)
            ring = None
        elif first_after_event:
            start = t + U(0.4, 2.0)
        elif overl and last_a is not None and busy() > t:
            start = max(t + U(0.3, 0.8), last_a["start"] + U(0.3, 0.6) * (last_a["full_end"] - last_a["start"]))
        else:
            start = max(t, busy()) + U(0.4, 2.0)
        placed.append((i, start))
        if at_door:
            p = "door"
        elif tu["addressee"] == "caller" or in_call:
            p = spec["call_pos"]
        else:
            p = "across" if rng.random() < P_ASST_FAR else "near"
        end = tl.speech(f"u{i}", tu["text"], spec["user"], "user", start, p, rirs[p], ulevel(rng, p))
        t_dec = end + 0.2
        respond = to_a and tu["act"] not in ("backchannel", "keep_going")
        speaking = last_a is not None and last_a["start"] < start and t_dec < last_a["end"] - 0.05 and overl
        if first_after_event:
            first_reaction_done = True
        if tu["addressee"] == "caller":
            in_call = True
        if to_a and tu["act"] == "return":
            in_call = False
        if i == last_away_idx:
            away_seen = True
        cat = ("control" if spec["etype"] in ("none", "ignored") else
               "pickup" if tu["act"] == "answer" else
               "away" if tu["addressee"] in ("caller", "visitor") else
               "return" if away_seen else
               "mid" if last_away_idx > i and any(x["kind"] == "speech" and x["speaker"] == "user" and
                                                  x["addressee"] in ("caller", "visitor") for x in turns[:i]) else
               "control")
        if speaking:
            stop = not (to_a and tu["act"] in ("backchannel", "keep_going"))
            if stop:
                last_a["end"] = round(t_dec, 4)
            tl.point(t_dec, "RS" if stop else "S", {"S": "stop" if stop else "continue",
                                                    "R": ("respond" if respond else "not") if stop else None},
                     line=f"u{i}", category="stop_or_not" if not stop else cat)
            t = t_dec if stop else end
            if stop:
                in_turn = False
        else:
            if n_user > 1:
                tl.point(t_dec, "R", {"R": "respond" if respond else "not", "S": None}, line=f"u{i}", category=cat)
            t, in_turn = end, False
    if ring:
        add_ring(max(t + 0.5, ring["start"] + (U(15.0, 30.0) if ring["ignored"] else 1.0)))
    return tl, placed


BUILDERS = {"r_hear": build_r_hear, "r_react": build_r_react, "s_react": build_s_react, "s_move": build_s_move,
            "floor": build_floor, "report": build_report, "episode": build_episode}


def safe(s):
    return re.sub(r"[^A-Za-z0-9_.-]+", "_", s)
